#!/usr/bin/env node
/**
 * Resolve the storefront's Medusa identifiers before the server starts.
 *
 * WHY
 *
 * The storefront talks to the Store API, which refuses every request without a
 * valid `x-publishable-api-key`. The key is generated by Medusa the first time a
 * database is provisioned, so it cannot be written into `.env` in advance — and
 * a key copied from another environment (or from a database volume that has
 * since been deleted) fails with "Publishable key not valid", which looks like a
 * code fault rather than stale configuration.
 *
 * So the key, the region and the sales channel are read from the running backend
 * at start-up, using the admin account the storefront already holds for its admin
 * panel. The result is written as shell assignments that the entrypoint sources
 * into the server's environment.
 *
 * This is a deliberate best effort: if the backend is unreachable or the admin
 * account is wrong, it logs why and leaves the existing environment alone. A
 * storefront that starts and complains about a missing key is easier to diagnose
 * than one that refuses to boot.
 */

import { writeFileSync } from "node:fs";

const OUT = process.env.RUNTIME_ENV_FILE || "/tmp/snehavrinda-runtime.env";

const BACKEND = (
  process.env.MEDUSA_BACKEND_URL ||
  process.env.NEXT_PUBLIC_MEDUSA_BACKEND_URL ||
  "http://backend:9000"
).replace(/\/+$/, "");

const EMAIL = process.env.MEDUSA_ADMIN_EMAIL || process.env.ADMIN_EMAIL || "";
const PASSWORD = process.env.MEDUSA_ADMIN_PASSWORD || process.env.ADMIN_PASSWORD || "";
const CURRENCY = (process.env.MEDUSA_CURRENCY_CODE || "inr").toLowerCase();

const log = (msg) => console.log(`[runtime-env] ${msg}`);
const warn = (msg) => console.warn(`[runtime-env] ${msg}`);

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function api(path, options = {}) {
  const headers = { Accept: "application/json", ...(options.headers || {}) };
  if (options.body) headers["Content-Type"] = "application/json";
  const res = await fetch(`${BACKEND}${path}`, {
    method: options.method || "GET",
    headers,
    body: options.body ? JSON.stringify(options.body) : undefined,
    signal: AbortSignal.timeout(15_000),
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { ok: res.ok, status: res.status, body };
}

/** Shell-quote a value so sourcing the file cannot execute anything. */
function quote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}

async function adminToken() {
  if (!EMAIL || !PASSWORD) return null;
  for (let attempt = 1; attempt <= 20; attempt++) {
    try {
      const res = await api("/auth/user/emailpass", {
        method: "POST",
        body: { email: EMAIL, password: PASSWORD },
      });
      const token = res.body?.token || res.body?.session?.token;
      if (res.ok && token) return token;
      if (attempt === 20) {
        warn(`admin authentication failed (${res.status}) — keeping .env values`);
        return null;
      }
    } catch (err) {
      if (attempt === 20) {
        warn(`backend unreachable (${err.message}) — keeping .env values`);
        return null;
      }
    }
    await sleep(2_000);
  }
  return null;
}

async function main() {
  const token = await adminToken();
  if (!token) {
    warn("no admin token; falling back to the environment variables from compose");
    return;
  }

  const auth = { Authorization: `Bearer ${token}` };
  const resolved = {};

  // ── publishable key ──
  //
  // More than one publishable key can exist (Medusa creates a "Default" one
  // with its default sales channel on migration), and a key only sees the
  // products of the channel it is attached to. Picking the first key therefore
  // selected a channel with no products and the shop rendered empty while every
  // product sat in the database. Ask each key what it can actually see and keep
  // the one that returns products.
  const keys = await api(
    "/admin/api-keys?type=publishable&fields=id,title,token,*sales_channels",
    { headers: auth }
  );
  const list = keys.ok ? keys.body.api_keys ?? [] : [];
  const ranked = [
    ...list.filter((k) => (k.sales_channels ?? []).length > 0),
    ...list.filter((k) => (k.sales_channels ?? []).length === 0),
  ];

  let chosen = null;
  for (const candidate of ranked) {
    if (!candidate.token) continue;
    const probe = await api("/store/products?limit=1", {
      headers: { "x-publishable-api-key": candidate.token },
    });
    if (probe.ok && (probe.body?.products ?? []).length > 0) {
      chosen = candidate;
      break;
    }
    if (!chosen && probe.ok) chosen = chosen ?? candidate;
  }
  chosen = chosen ?? ranked[0];

  if (chosen?.token) {
    resolved.MEDUSA_PUBLISHABLE_KEY = chosen.token;
    const channelId = (chosen.sales_channels ?? [])[0]?.id;
    if (channelId) resolved.MEDUSA_SALES_CHANNEL_ID = channelId;
    log(`publishable key "${chosen.title}" resolved from the backend`);
  } else {
    warn("no publishable key exists yet — the seed service creates one");
  }

  // ── region ──
  const regions = await api("/admin/regions?limit=200", { headers: auth });
  const regionList = regions.ok ? regions.body.regions ?? [] : [];
  const region = regionList.find(
    (r) => String(r.currency_code || "").toLowerCase() === CURRENCY
  );
  if (region) {
    resolved.MEDUSA_REGION_ID = region.id;
    log(`region "${region.name}" (${region.id}) resolved from the backend`);
  } else if (regionList.length) {
    resolved.MEDUSA_REGION_ID = regionList[0].id;
    warn(`no ${CURRENCY} region; using "${regionList[0].name}"`);
  } else {
    warn(`no ${CURRENCY} region exists — the seed service creates one`);
  }

  if (!Object.keys(resolved).length) return;

  const file = Object.entries(resolved)
    .map(([key, value]) => `${key}=${quote(value)}`)
    .join("\n");
  writeFileSync(OUT, `${file}\n`, "utf8");
  log(`wrote ${Object.keys(resolved).join(", ")} to ${OUT}`);
}

main().catch((err) => {
  warn(`unexpected failure: ${err.message} — starting anyway`);
});
